parameters.jsCode:
// Parse the Claude response into structured data
const response = $input.first().json;
let storyData;

try {
  // Extract JSON from the response
  const content = response.message?.content || response.text || response;
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    storyData = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in response');
  }
} catch (e) {
  throw new Error('Failed to parse story: ' + e.message);
}

// Get queue data from previous node
const queueData = $('Supabase - Create Queue Entry').first().json;

return {
  json: {
    queue_id: queueData.id,
    ...storyData,
    category: queueData.category,
    age_band: queueData.age_band,
    sight_words: queueData.sight_words,
    page_count: storyData.pages.length
  }
};

// Prepare pages for loop processing
const storyData = $('Parse Story Response').first().json;
const story = $('Supabase - Create Story').first().json;

return storyData.pages.map(page => ({
  json: {
    story_id: story.id,
    queue_id: storyData.queue_id,
    page_number: page.page_number,
    text_content: page.text,
    illustration_description: page.illustration_description,
    illustration_alt_text: page.illustration_description.substring(0, 200),
    sight_words_used: page.sight_words_used || [],
    age_band: storyData.age_band,
    character_name: $('Supabase - Create Queue Entry').first().json.character_name
  }
}));

// Build the public URL for the uploaded image
const pageData = $('Loop Over Pages').first().json;
const supabaseUrl = 'YOUR_SUPABASE_URL'; // Replace with your Supabase URL
const imagePath = `pages/${pageData.story_id}/page-${pageData.page_number}.png`;
const publicUrl = `${supabaseUrl}/storage/v1/object/public/story-images/${imagePath}`;

return {
  json: {
    ...pageData,
    illustration_url: publicUrl
  }
};
